 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationExpiredAtAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getExpiredAt returns null on a freshly created holder.
     */
    public function testExpiredAtNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationExpiredAtAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isExpiredAtAssigned());
        $this->assertNull($holder->getExpiredAt());
    }
}
